from pathlib import Path
import json,html,collections,csv
ROOT=Path(__file__).resolve().parents[1]
B=json.loads((ROOT/'data/analysis_bundle.json').read_text())
S=json.loads((ROOT/'analysis/system_specification.json').read_text())
C={(c['sheet'],c['cell']):c for c in B['workbook']['cells']}
def v(sh,a):return C.get((sh,a),{}).get('value')
def esc(s):return html.escape(str(s))
def show(x):
    if x is None:return '<span class="muted">空/未填</span>'
    if isinstance(x,float):return f'{x:,.10f}'.rstrip('0').rstrip('.')
    if isinstance(x,(list,dict)):return esc(json.dumps(x,ensure_ascii=False))
    return esc(x)
def table(headers,rows):
    return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+show(x)+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def sec(id,title,body):return f'<section id="{id}"><h2>{title}</h2>{body}</section>'
def p(x):return '<p>'+x+'</p>'
def source(sh,a):return f'<a href="#explorer" class="celllink" data-sheet="{esc(sh)}" data-cell="{a}">{esc(sh)}!{a}</a>'
