pages.append(sec('outputs','10 · 541项报表/辅助输出对应',p('逐项保留坐标、原公式、缓存值和直接引用。相同公式族见第12节；完整的输出→最终叶子输入展开另在<code>output_input_lineage.csv</code>，共96,729行，包含公式涉及的空白源单元格与未选条件分支，是静态潜在依赖，不全部代表当前分支已生效。TODAY等无单元格输入的驱动由规则R29记录。')+'<label>筛选输出 <input id="output-search" placeholder="输入工作表、单元格、标签或公式"></label><div id="outputs-table"></div>'))
pages.append(sec('explorer','11 · 全部数据与公式检索',p('6,926个单元格全部可查。可以用“Expenses Lists!M70”精确定位，点击某行查看原始内容、公式、数字格式、直接依赖及下游使用者。未显示在有内容清单里的空白引用仍会出现在依赖详情及CSV中。')+'<div class="controls"><select id="sheet-filter"><option value="">全部工作表</option>'+''.join(f'<option>{esc(s["name"])}</option>' for s in B['workbook']['sheets'])+'</select><select id="kind-filter"><option value="">数据及公式</option><option value="formula">仅公式</option><option value="literal">仅常量/文字</option></select><input id="cell-search" placeholder="坐标、摘要、字段、公式或金额"><button id="prev">上一页</button><button id="next">下一页</button></div><p id="cell-count"></p><div id="cells-table"></div><aside id="cell-detail"><p>选择一个单元格查看对应关系。</p></aside>'))
