pages.append(sec('acceptance','13 · 迁移步骤与验收',table(['阶段','执行内容','完成条件'],[['1 原始归档','只读快照、哈希、全单元格/公式/依赖提取','源文件可复原、行数与公式数覆盖一致'],['2 主数据与口径认定','主体、船舶、科目、币种、责任方、期初及截止日','开放问题有决议，政策版本及负责人留痕'],['3 去重及分摊','总清单与分类候选归并；3000拆分等单独映射','每个来源行对应目标业务或明确排除理由'],['4 资金与单据','银行22条、CTM22条、9条有日期收款、发票及外部附件核销','多对多匹配、退款和跨船往来有依据；未核销项单列'],['5 并行报表','旧表兼容结果与新规则结果分别验证','差异能追溯，原表错误不以调账隐去'],['6 上线关账','员工按新表单录入，月结、权限、审计和备份','核心验收案例通过，历史数据锁定']])+table(['案例','主题','验收要求'],S['acceptance'])+p('暂不能从单一快照恢复的内容：全部外部凭证、逐次审批历史、实际历史汇率来源、完整银行核销、真正期初资产负债、税项及真实库存数量。已标记“待确认/待补”，不影响本次结构、数据和公式的全量提取。')))
