catalog=[('all_cells.csv','全部6926个有内容单元格、原值/公式/缓存、格式与字段含义'),('all_formulas.csv','全部2722个公式，逐单元格原文'),('formula_references.csv','4963个直接引用操作数，范围保留'),('cell_dependencies.csv','14626条展开引用边，含空白源与INDEX潜在整列'),('formula_groups.csv','294个公式族及全部成员'),('recalculation_checks.csv','逐公式缓存与独立复算对照'),('sheet_inventory.csv','全部工作表、合并区、数据验证和结构'),('sheet_dependencies.csv','跨表引用关系汇总'),('field_dictionary.csv','原表列/区域到平台字段及含义'),('report_output_mapping.csv','541个报表和辅助结果、公式、引用及叶子输入数'),('output_input_lineage.csv','96729条输出到最终潜在输入的追溯'),('business_records.csv','232个原表摘要行（含重复、计划及调整；不等于独立交易数）'),('bank_transactions.csv','全部22条银行流水'),('account_codes.csv','两套共192条编码及名称、部门'),('expenses_missing_status.csv','24条有金额但状态为空的原表行，含重复视图'),('amount_differences.csv','18条订单/验收/发票阶段差异'),('duplicate_view_candidates.csv','总清单与分类页98个候选对应关系'),('relationship_evidence.csv','14条人工分析的银行、分摊及CTM关联证据'),('bank_match_candidates.csv','22条银行流水逐条候选，未匹配也保留'),('findings.csv','25项异常/缺陷/待确认证据'),('workbook_raw.json','原始结构和精确值/公式；不转义公式文本'),('analysis_bundle.json','字段、记录、输出、关系及分析数据完整JSON'),('dependency_model.json','全部引用、依赖、公式组及复算JSON')]
pages.append(sec('downloads','15 · 文件目录与使用说明',p('建议先看本报告第1—7节，再由财务与开发共同评审第8—14节。JSON是保留精确公式和结构的机器接口，CSV为UTF-8 BOM方便Excel查看。CSV内以=、+、-、@起头的文本加了前导单引号，使公式保持文本；JSON及本报告保留原公式。数字金额仍按数字值导出。')+table(['文件','内容'],[[name,desc] for name,desc in catalog])+p('<a href="analysis/system_specification.json">system_specification.json</a>包含45条规则、实体、8个录入入口、18条验收及12个待确认问题。<a href="README.txt">README.txt</a>为目录说明。<code>source/</code>保存原始xlsx只读副本，<code>tools/</code>保存可复现提取分析脚本。')+p('源SHA-256：<code>'+B['workbook']['source_sha256']+'</code>。核对用日期固定为2026-10-14；分析制作日为2026-10-15。无隐藏页、隐藏行列、命名范围或外部工作簿链接；含40条数据验证规则（按原表规则数统计）。')))
pages[-1]=pages[-1].replace('</section>', '<details><summary>直接打开数据文件</summary><ul>'+''.join('<li><a href="data/'+name+'">'+name+'</a> — '+esc(desc)+'</li>' for name,desc in catalog)+'</ul></details>'+p('验证限制：独立复算及离线JavaScript逻辑可检查。自动审批拒绝启动本机HTTP预览服务，原因是财务目录可能向本地进程暴露；隔离浏览器也无法启动，因此未完成浏览器视觉检查。报告是自包含本地HTML，不依赖HTTP服务。')+'</section>')
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f6f8fb;color:#172b3a;font:15px/1.7 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}header{padding:38px 5vw 26px;background:#142e43;color:white}header h1{font-size:30px;margin:0 0 8px}header p{margin:0;color:#cfdeea}nav{position:sticky;top:0;padding:12px 5vw;background:#fff;border-bottom:1px solid #d5dfe8;z-index:4;display:flex;gap:16px;overflow:auto;white-space:nowrap}a{color:#14639a;text-decoration:none}a:hover{text-decoration:underline}main{max-width:1560px;margin:auto;padding:20px 4vw 60px}section{background:white;margin:24px 0;padding:28px;border:1px solid #dde5ec;border-radius:10px;scroll-margin-top:65px}h2{font-size:23px;margin:0 0 18px;color:#163f5b}p{margin:12px 0}.muted{color:#71808d}.tablewrap{overflow:auto;margin:16px 0;max-height:720px}table{border-collapse:collapse;width:100%;font-size:13px;line-height:1.65}th{background:#e8eff5;color:#24445b;position:sticky;top:0;z-index:1;text-align:left;font-weight:650}td,th{border-bottom:1px solid #e0e7ed;padding:10px 12px;vertical-align:top;min-width:88px;max-width:620px;overflow-wrap:anywhere}tbody tr:nth-child(even){background:#fafbfd}tbody tr:hover{background:#eef6fc}code{font-family:Menlo,Consolas,monospace;font-size:12px;overflow-wrap:anywhere;color:#1b587a}pre{white-space:pre-wrap;word-break:break-word;background:#f2f6f9;padding:15px;border-radius:6px;font-size:12px}input,select,button{font:inherit;padding:8px 11px;border:1px solid #b9cbd8;border-radius:5px;background:white}input{min-width:280px}button{cursor:pointer;color:#145579}button:hover{background:#eaf3fa}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:24px 0}.cards div{border-left:3px solid #377a9d;padding:12px 16px;background:#f3f7fa}.cards strong{display:block;font-size:27px;color:#164d6f}.flow{display:flex;align-items:center;gap:10px;margin:18px 0}.flow div{flex:1;padding:18px;border:1px solid #c9dce8;background:#f4f8fb;border-radius:8px}.controls{display:flex;gap:8px;flex-wrap:wrap}details{margin:22px 0}summary{cursor:pointer;font-weight:600;color:#205f87}#cell-detail{border-left:4px solid #548aa9;padding:16px;background:#f3f7fa;margin-top:20px;max-height:700px;overflow:auto}#cells-table tr{cursor:pointer}#cells-table td:nth-child(6){font-family:Menlo,Consolas,monospace;font-size:11px}li{margin:14px 0}.pill{display:inline-block;border:1px solid #cbdce6;border-radius:12px;padding:2px 9px;margin:3px;font-size:12px}.alert{background:#fff5e9;border-left:3px solid #cc8730;padding:12px 16px}footer{text-align:center;color:#6a7c8b;padding:20px}@media(max-width:800px){header h1{font-size:24px}main{padding:8px}section{padding:16px}.cards{grid-template-columns:1fr 1fr}.flow{flex-direction:column}.flow div{width:100%}input{min-width:0;width:100%}}@media print{nav,.controls,button{display:none}section{break-inside:auto;border:0}.tablewrap{max-height:none;overflow:visible}header{background:white;color:#142e43}th{position:static}}'''
payload=json.dumps(dict(cells=B['workbook']['cells'],sheets=B['workbook']['sheets'],outputs=B['outputs'],references=B['dependencies'],checks=B['checks']),ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
js='''const DATA=JSON.parse(document.getElementById('payload').textContent);const $=id=>document.getElementById(id);const e=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const fmt=x=>x===null||x===undefined?'<span class="muted">空/未填</span>':typeof x==='number'?x.toLocaleString('en-US',{maximumFractionDigits:10}):e(x);const key=(s,c)=>s+'!'+c;const bykey=new Map(DATA.cells.map(c=>[key(c.sheet,c.cell),c]));const refs=new Map();for(const r of DATA.references){const k=key(r.formula_sheet,r.formula_cell);if(!refs.has(k))refs.set(k,[]);refs.get(k).push(r)}const checks=new Map(DATA.checks.map(c=>[key(c.sheet,c.cell),c]));const colnum=s=>[...s].reduce((n,c)=>n*26+c.charCodeAt(0)-64,0);const colstr=n=>{let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)}return s};function expand(r){const rr=r.reference.split('!').pop().replace(/\$/g,'');const m=rr.match(/^([A-Z]+)(\d+)?(?::([A-Z]+)(\d+)?)?$/);if(!m)return[];if(r.whole_column){return DATA.cells.filter(c=>c.sheet===r.target_sheet&&c.column>=colnum(m[1])&&c.column<=colnum(m[3]||m[1])).map(c=>key(c.sheet,c.cell))}let out=[];for(let y=+(m[2]||1);y<=+(m[4]||m[2]||1);y++)for(let x=colnum(m[1]);x<=colnum(m[3]||m[1]);x++)out.push(key(r.target_sheet,colstr(x)+y));return out}const downstream=new Map();for(const r of DATA.references){for(const k of expand(r)){if(!downstream.has(k))downstream.set(k,new Set());downstream.get(k).add(key(r.formula_sheet,r.formula_cell))}}let page=0;const size=80;function mkTable(h,rows){return '<div class="tablewrap"><table><thead><tr>'+h.map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}function cellsRender(){const sh=$('sheet-filter').value,kind=$('kind-filter').value,q=$('cell-search').value.trim().toLowerCase();const arr=DATA.cells.filter(c=>(!sh||c.sheet===sh)&&(!kind||c.kind===kind)&&(!q||[key(c.sheet,c.cell),c.value,c.raw_value,c.field,c.row_context,c.semantic].join(' ').toLowerCase().includes(q)));page=Math.min(page,Math.max(0,Math.ceil(arr.length/size)-1));$('cell-count').textContent=`匹配 ${arr.length} 个单元格 · 第 ${page+1} / ${Math.max(1,Math.ceil(arr.length/size))} 页 · 点击行查看关联`;const rows=arr.slice(page*size,(page+1)*size);$('cells-table').innerHTML=mkTable(['工作表','单元格','类型','业务上下文 / 字段','保存值','原始公式或常量'],rows.map(c=>[e(c.sheet),e(c.cell),c.kind==='formula'?'公式':'常量',e((c.row_context||'')+(c.field?' / '+c.field:'')),fmt(c.value),e(c.raw_value)]));$('cells-table').querySelectorAll('tbody tr').forEach((tr,i)=>tr.onclick=()=>detail(rows[i]));$('prev').disabled=page===0;$('next').disabled=(page+1)*size>=arr.length}function link(k){const c=bykey.get(k);return '<a href="#explorer" class="keylink" data-key="'+e(k)+'">'+e(k)+'</a>'+(c?' = '+fmt(c.value):'（空白引用）')}function detail(c){const k=key(c.sheet,c.cell);const rs=refs.get(k)||[];const ds=[...(downstream.get(k)||[])];const ck=checks.get(k);$('cell-detail').innerHTML='<h3>'+e(k)+'</h3><p><b>平台字段：</b>'+e(c.field||'报表/字典/辅助区域')+'<br><b>业务上下文：</b>'+e(c.row_context)+'<br><b>含义：</b>'+e(c.semantic)+'</p><p><b>缓存值：</b>'+fmt(c.value)+'　<b>类型：</b>'+e(c.data_type)+'　<b>数字格式：</b><code>'+e(c.number_format)+'</code></p><pre>'+e(c.raw_value)+'</pre>'+(ck?'<p>独立复算：'+e(ck.status)+' · '+fmt(ck.recomputed)+(ck.error?' · '+e(ck.error):'')+'（固定2026-10-14）</p>':'')+(c.array_range?'<p>数组范围：'+e(c.array_range)+'</p>':'')+'<h4>直接引用（原范围与展开值）</h4>'+(rs.length?rs.map(r=>'<details><summary>'+e(r.reference)+' · '+r.expanded_cells+' 个位置'+(r.whole_column?'（INDEX潜在范围，实际选中J14）':'')+'</summary><p>'+expand(r).map(link).join('<br>')+'</p></details>').join(''):'<p>无单元格引用；常量或TODAY等环境驱动。</p>')+'<h4>直接下游（含潜在INDEX整列引用）</h4><p>'+(ds.length?ds.map(link).join('<br>'):'无下游公式')+'</p>';bindkeys()}function bindkeys(){document.querySelectorAll('.keylink').forEach(a=>a.onclick=()=>{const c=bykey.get(a.dataset.key);if(c){$('sheet-filter').value=c.sheet;$('cell-search').value=c.cell;$('kind-filter').value='';page=0;cellsRender();detail(c)}else $('cell-detail').innerHTML='<p>'+e(a.dataset.key)+' 是被引用的空白源单元格，原文件无值。</p>'})}function outRender(){const q=$('output-search').value.trim().toLowerCase();let a=DATA.outputs.filter(o=>!q||JSON.stringify(o).toLowerCase().includes(q));$('outputs-table').innerHTML='<p>匹配 '+a.length+' 项输出</p>'+mkTable(['编号','工作表 / 单元格','上下文标签 / 字段','保存值','原公式','直接引用','最终潜在输入数'],a.map(o=>[e(o.output_id),'<a href="#explorer" class="keylink" data-key="'+e(key(o.sheet,o.cell))+'">'+e(key(o.sheet,o.cell))+'</a>',e(o.label+(o.field?' / '+o.field:'')),fmt(o.value),e(o.formula),e(o.direct_refs.join(' ; ')),o.leaf_input_count]));bindkeys()}for(const id of ['sheet-filter','kind-filter','cell-search'])$(id).addEventListener('input',()=>{page=0;cellsRender()});$('prev').onclick=()=>{page--;cellsRender()};$('next').onclick=()=>{page++;cellsRender()};$('output-search').oninput=outRender;document.querySelectorAll('.celllink').forEach(a=>a.onclick=()=>{const c=bykey.get(key(a.dataset.sheet,a.dataset.cell));if(c)detail(c)});cellsRender();outRender();'''
links=[('overview','结论'),('metrics','汇总'),('sheets','工作表'),('flow','关联'),('rules','规则'),('findings','异常'),('forms','录入流程'),('fields','字段字典'),('entities','数据模型'),('outputs','报表映射'),('explorer','全部数据/公式'),('groups','公式族'),('acceptance','迁移验收'),('questions','待确认'),('downloads','文件目录')]
